package com.guocheng.mediapocket;
import android.app.*;import android.os.*;import android.view.*;import android.widget.*;import org.json.*;import java.util.*;import java.util.concurrent.*;
/** Source discovery is only started on user selection or after playback failure. */
public final class PlaybackSitePicker {
 static final ExecutorService IO=Executors.newFixedThreadPool(2),REQUEST=Executors.newFixedThreadPool(2);
 static final Map<Activity,State> STATES=Collections.synchronizedMap(new WeakHashMap<Activity,State>());
 static final class State {volatile int token;volatile boolean automatic;Set<String> tried=Collections.synchronizedSet(new HashSet<String>());}
 static State state(Activity a){State s=STATES.get(a);if(s==null){s=new State();STATES.put(a,s);}return s;}
 static JSONObject meta(Activity a){Object m=OnlineSubtitleSearch.field(a,"meta");return m instanceof JSONObject?(JSONObject)m:new JSONObject();}
 static boolean alive(Activity a){return !a.isFinishing()&&Boolean.TRUE.equals(OnlineSubtitleSearch.field(a,"alive"));}
 static String title(JSONObject m){return MediaMatchRules.clean(m.optString("fusion.title",m.optString("name")));}
 static JSONObject request(Activity a,FusionCatalog.Session s,String op,String value,String flag,int page,long timeout)throws Exception{Future<JSONObject> f=REQUEST.submit(()->FusionCatalog.request(a,s,op,value,flag,page));try{return f.get(Math.max(1,timeout),TimeUnit.MILLISECONDS);}finally{f.cancel(true);}}
 public static void attach(Object session){try{Object owner=OnlineSubtitleSearch.field(session,"a");if(!(owner instanceof Activity))return;Activity a=(Activity)owner;if(!meta(a).has("fusion.config"))return;Object bottom=OnlineSubtitleSearch.field(a,"bottom");if(!(bottom instanceof ViewGroup))return;LinearLayout row=null;ViewGroup group=(ViewGroup)bottom;for(int i=0;i<group.getChildCount();i++)if(group.getChildAt(i) instanceof HorizontalScrollView){View child=((HorizontalScrollView)group.getChildAt(i)).getChildAt(0);if(child instanceof LinearLayout)row=(LinearLayout)child;}if(row==null||row.findViewWithTag("tv-site-picker")!=null)return;int count=FusionCatalog.session(a,meta(a).optString("fusion.config"),meta(a).optString("fusion.site")).config.optJSONArray("sites").length();Button button=(Button)OnlineSubtitleSearch.call(a,"btn",new Class<?>[]{String.class,Runnable.class},"影视仓源 · "+count,(Runnable)()->show(a));button.setTag("tv-site-picker");row.addView(button,0);Button episodes=(Button)OnlineSubtitleSearch.call(a,"btn",new Class<?>[]{String.class,Runnable.class},"选集",(Runnable)()->selectEpisode(a));episodes.setTag("tv-episode-picker");row.addView(episodes,1);}catch(Exception ignored){}}
 static void show(Activity a){State state=state(a);final int token=++state.token;state.automatic=false;try{JSONObject m=meta(a);FusionCatalog.Session session=FusionCatalog.session(a,m.optString("fusion.config"),m.optString("fusion.site"));new SourcePickerDialog(a,session,title(m),(selected,item)->{if(alive(a)&&state.token==token)detail(a,selected,item,token);});}catch(Exception e){message(a,"站点列表读取失败："+e.getClass().getSimpleName());}}
 static void search(Activity a,String config,JSONObject site){if(site==null)return;if(site.optInt("type",3)!=3){message(a,"此站点类型暂不支持播放窗口搜索。");return;}State state=state(a);final int token=++state.token;state.automatic=false;EditText word=new EditText(a);word.setSingleLine(true);word.setText(title(meta(a)));new AlertDialog.Builder(a).setTitle("搜索 · "+site.optString("name")).setView(word).setPositiveButton("查找同片",(d,n)->{String query=word.getText().toString().trim();if(query.isEmpty())return;ProgressDialog wait=ProgressDialog.show(a,"正在查找同片",site.optString("name"),true,true);wait.setOnCancelListener(x->state.token++);IO.execute(()->{try{FusionCatalog.Session s=FusionCatalog.session(a,config,site.optString("key"));JSONArray results=SourceSearchClient.run(a,s,query,45000);a.runOnUiThread(()->{wait.dismiss();if(!alive(a)||state.token!=token)return;if(results==null||results.length()==0){message(a,"此站点未找到影片，当前视频保持播放。可换站点或改用其他片名。");return;}String[] labels=new String[Math.min(100,results.length())];for(int i=0;i<labels.length;i++){JSONObject v=results.optJSONObject(i);labels[i]=v.optString("vod_name")+" · "+v.optString("vod_year")+" · "+v.optString("vod_remarks");}new AlertDialog.Builder(a).setTitle("确认同一影片 · "+site.optString("name")).setItems(labels,(x,i)->detail(a,s,results.optJSONObject(i),token)).setNegativeButton("取消",null).show();});}catch(Exception e){a.runOnUiThread(()->{wait.dismiss();if(alive(a)&&state.token==token)message(a,"此站点搜索失败："+SourceSearchClient.reason(e)+"。当前视频保持播放。");});}});}).setNegativeButton("取消",null).show();}
 static List<FusionPlaybackRules.Route> routes(JSONObject detail,JSONObject m){return routes(detail,m,true);}
 static List<FusionPlaybackRules.Route> routes(JSONObject detail,JSONObject m,boolean confirmedOnly){String wanted=m.optString("subtitleEpisode");boolean episodic=FusionPlaybackRules.episode(wanted,"").number>0||m.optString("fusion.mediaType").equals("series");return FusionPlaybackRules.routeList(detail.optString("vod_play_from"),detail.optString("vod_play_url"),wanted,episodic,confirmedOnly,detail.optString("vod_name"));}
 static void detail(Activity a,FusionCatalog.Session session,JSONObject item,int token){ProgressDialog wait=ProgressDialog.show(a,"正在读取线路","匹配当前影片与集数…",true,true);State state=state(a);wait.setOnCancelListener(x->state.token++);IO.execute(()->{try{JSONArray list=request(a,session,"detail",item.optString("vod_id"),"",1,35000).optJSONArray("list");JSONObject d=list==null?null:list.optJSONObject(0);if(d==null)throw new Exception("未返回详情");List<FusionPlaybackRules.Route> verified=routes(d,meta(a));final boolean confirm=verified.isEmpty();List<FusionPlaybackRules.Route> routes=confirm?routes(d,meta(a),false):verified;SourceSearchClient.record(a,session.site.optString("name"),title(meta(a)),"详情返回线路 "+routes(d,meta(a),false).size()+" 条 · 已确认同集 "+verified.size()+" 条");a.runOnUiThread(()->{wait.dismiss();if(!alive(a)||state.token!=token)return;if(routes.isEmpty()){message(a,"本站详情没有返回选集地址，未切换视频。");return;}String[] labels=new String[routes.size()];for(int i=0;i<labels.length;i++)labels[i]=routes.get(i).flag+" · "+routes.get(i).name;new AlertDialog.Builder(a).setTitle((confirm?"未确认季号，请手动确认同集 · ":"选择播放线路 · ")+d.optString("vod_name")).setItems(labels,(x,n)->{FusionPlaybackRules.Route selected=routes.get(n);if(!confirm){resolve(a,session,d,selected,token);return;}String wanted=meta(a).optString("subtitleEpisode");if(FusionPlaybackRules.differentEpisode(wanted,selected.name,selected.flag+" "+d.optString("vod_name"))){message(a,"所选「"+selected.name+"」与当前「"+wanted+"」集数或季号不同，未切换。");return;}new AlertDialog.Builder(a).setTitle("确认是当前这一集").setMessage("当前："+wanted+"\n所选："+selected.flag+" · "+selected.name+"\n站点未完整标明季集，请核对。确认后按当前进度续播。").setPositiveButton("是同一集，切换",(z,i)->resolve(a,session,d,selected,token)).setNegativeButton("取消",null).show();}).setNegativeButton("取消",null).show();});}catch(Exception e){a.runOnUiThread(()->{wait.dismiss();if(alive(a)&&state.token==token)message(a,"详情读取失败："+e.getClass().getSimpleName());});}});}
 static JSONObject stream(Activity a,FusionCatalog.Session session,FusionPlaybackRules.Route route,long timeout)throws Exception{JSONObject r=request(a,session,"player",route.value,route.flag,1,timeout);if(r.optInt("parse",0)!=0||r.optInt("jx",0)!=0)throw new Exception("该线路需要网页解析，暂未支持");String raw=r.optString("url");if(raw.isEmpty())throw new Exception("未返回播放地址");JSONObject headers=r.optJSONObject("header");if(headers==null&&r.opt("header") instanceof String)try{headers=new JSONObject(r.optString("header"));}catch(Exception ignored){}if(headers==null)headers=new JSONObject();return new JSONObject().put("url",TvBoxRules.resolve(session.url,raw)).put("name",session.site.optString("name")+" · "+route.flag).put("behaviorHints",new JSONObject().put("proxyHeaders",new JSONObject().put("request",headers)));}
 static void resolve(Activity a,FusionCatalog.Session s,JSONObject detail,FusionPlaybackRules.Route route,int token){State state=state(a);ProgressDialog wait=ProgressDialog.show(a,"正在取得新地址",s.site.optString("name"),true,true);wait.setOnCancelListener(x->state.token++);IO.execute(()->{try{JSONObject stream=stream(a,s,route,35000);a.runOnUiThread(()->{wait.dismiss();if(alive(a)&&state.token==token){apply(a,s,stream,route.name);try{meta(a).put("fusion.video",detail.optString("vod_id")).put("fusion.flag",route.flag);}catch(Exception ignored){}}});}catch(Exception e){a.runOnUiThread(()->{wait.dismiss();if(alive(a)&&state.token==token)message(a,"新线路地址获取失败："+e.getMessage()+"。未切换当前视频。");});}});}
 static void apply(Activity a,FusionCatalog.Session s,JSONObject stream,String episode){try{Object queue=Class.forName("com.guocheng.mediapocket.SourceQueue").getConstructor(JSONObject.class,JSONArray.class).newInstance(stream,new JSONArray().put(stream));JSONObject m=new JSONObject(meta(a).toString());m.put("fusion.config",s.url).put("fusion.site",s.site.optString("key")).put("fusion.source",s.site.optString("name")).put("subtitleEpisode",m.optString("subtitleEpisode",episode));SourceSubtitleLoader.set(a,"queue",queue);SourceSubtitleLoader.set(a,"meta",m);Object budget=OnlineSubtitleSearch.field(a,"budget");OnlineSubtitleSearch.call(budget,"manualRestart",new Class<?>[]{long.class},SystemClock.elapsedRealtime());OnlineSubtitleSearch.call(a,"advance",new Class<?>[]{String.class},"切换影视仓 · "+s.site.optString("name"));FullscreenMode.sync(a);Toast.makeText(a,"已切换 · "+s.site.optString("name"),Toast.LENGTH_SHORT).show();}catch(Exception e){message(a,"播放源切换失败："+e.getClass().getSimpleName());}}
 static boolean exact(JSONObject item,JSONObject m){String year=m.optString("releaseInfo"),candidate=item.optString("vod_year");return SourceSearchRules.sameFilm(item.optString("vod_name"),candidate,title(m),year);}
 public static void onFailure(Object owner,String reason){try{if(!(owner instanceof Activity))return;Activity a=(Activity)owner;if(!alive(a)||!Boolean.TRUE.equals(OnlineSubtitleSearch.field(a,"active"))||Boolean.TRUE.equals(OnlineSubtitleSearch.field(a,"terminal"))||!Boolean.TRUE.equals(OnlineSubtitleSearch.field(a,"autoSwitch"))||!meta(a).has("fusion.config"))return;Object queue=OnlineSubtitleSearch.field(a,"queue");if(Boolean.TRUE.equals(OnlineSubtitleSearch.call(queue,"hasNext",new Class<?>[0])))return;automatic(a);}catch(Exception ignored){}}
 static void automatic(Activity a){State state=state(a);if(state.automatic)return;JSONObject m=meta(a);if(title(m).isEmpty())return;state.automatic=true;int token=++state.token;state.tried.add(m.optString("fusion.site"));status(a,"正在其他影视仓站点查找同片备用源…");IO.execute(()->{String result="未找到已确认同片、同集的可播放备用线路。可点影视仓源手动搜索。";try{FusionCatalog.Session initial=FusionCatalog.session(a,m.optString("fusion.config"),m.optString("fusion.site"));JSONArray sites=initial.config.optJSONArray("sites");long deadline=System.nanoTime()+TimeUnit.SECONDS.toNanos(90);int attempts=0;for(int i=0;i<sites.length()&&attempts<8&&System.nanoTime()<deadline;i++){if(!alive(a)||state.token!=token)return;JSONObject site=sites.optJSONObject(i);if(site==null||site.optInt("type",3)!=3||site.optInt("searchable",1)==0||!state.tried.add(site.optString("key")))continue;attempts++;try{FusionCatalog.Session s=FusionCatalog.session(a,initial.url,site.optString("key"));JSONArray list=SourceSearchClient.run(a,s,title(m),Math.min(45000,TimeUnit.NANOSECONDS.toMillis(deadline-System.nanoTime())));JSONObject match=null;int count=0;for(int n=0;list!=null&&n<Math.min(100,list.length());n++){JSONObject v=list.optJSONObject(n);if(v!=null&&exact(v,m)){match=v;count++;}}if(count!=1){SourceSearchClient.record(a,site.optString("name"),title(m),"原始结果 "+(list==null?0:list.length())+" 条 · 同片候选 "+count+" 条，未自动切换");continue;}JSONArray details=request(a,s,"detail",match.optString("vod_id"),"",1,Math.min(35000,Math.max(1,TimeUnit.NANOSECONDS.toMillis(deadline-System.nanoTime())))).optJSONArray("list");JSONObject detail=details==null?null:details.optJSONObject(0);if(detail==null)continue;List<FusionPlaybackRules.Route> routes=routes(detail,m);if(routes.isEmpty())continue;JSONObject stream=stream(a,s,routes.get(0),Math.min(35000,Math.max(1,TimeUnit.NANOSECONDS.toMillis(deadline-System.nanoTime()))));String ep=routes.get(0).name;a.runOnUiThread(()->{if(!alive(a)||state.token!=token)return;state.automatic=false;if(!Boolean.TRUE.equals(OnlineSubtitleSearch.field(a,"active")))return;apply(a,s,stream,ep);try{meta(a).put("fusion.video",detail.optString("vod_id")).put("fusion.flag",routes.get(0).flag);}catch(Exception ignored){}});return;}catch(Exception error){SourceSearchClient.record(a,site.optString("name"),title(m),"匹配或地址请求失败 · "+SourceSearchClient.reason(error));}}}catch(Exception e){result="备用站点读取失败，可点影视仓源手动选择。";}final String report=result;a.runOnUiThread(()->{if(alive(a)&&state.token==token){state.automatic=false;status(a,report);}});});}
 static void selectEpisode(Activity a){State state=state(a);state.automatic=false;int token=++state.token;JSONObject current=meta(a);String id=current.optString("fusion.video");if(id.isEmpty()){message(a,"当前影片没有站点详情标识，请从影视仓影片详情重新打开。");return;}ProgressDialog wait=ProgressDialog.show(a,"正在读取剧集","当前站点选集与线路…",true,true);wait.setOnCancelListener(x->state.token++);IO.execute(()->{try{FusionCatalog.Session session=FusionCatalog.session(a,current.optString("fusion.config"),current.optString("fusion.site"));JSONArray list=request(a,session,"detail",id,"",1,35000).optJSONArray("list");JSONObject detail=list==null?null:list.optJSONObject(0);if(detail==null)throw new Exception("未返回详情");List<FusionPlaybackRules.Route> choices=routes(detail,current,false);a.runOnUiThread(()->{wait.dismiss();if(!alive(a)||state.token!=token)return;if(choices.isEmpty()){message(a,"当前站点未返回选集地址。");return;}String[] labels=new String[choices.size()];FusionPlaybackRules.Episode wanted=FusionPlaybackRules.episode(current.optString("subtitleEpisode"),"");for(int i=0;i<labels.length;i++){FusionPlaybackRules.Route r=choices.get(i);FusionPlaybackRules.Episode ep=FusionPlaybackRules.episode(r.name,r.flag+" "+detail.optString("vod_name"));boolean same=FusionPlaybackRules.episodeKey(r.name).equals(FusionPlaybackRules.episodeKey(current.optString("subtitleEpisode")))||(wanted.number>0&&wanted.number==ep.number&&(ep.season<0||wanted.season<0||wanted.season==ep.season));labels[i]=(same?"● 当前集 · ":"")+r.flag+" · "+r.name;}new AlertDialog.Builder(a).setTitle("选集 · "+session.site.optString("name")).setItems(labels,(d,n)->openEpisode(a,session,detail,choices.get(n),token)).setNegativeButton("关闭",null).show();});}catch(Exception e){a.runOnUiThread(()->{wait.dismiss();if(alive(a)&&state.token==token)message(a,"选集读取失败："+SourceSearchClient.reason(e));});}});}
 static void openEpisode(Activity a,FusionCatalog.Session session,JSONObject detail,FusionPlaybackRules.Route route,int token){State state=state(a);ProgressDialog wait=ProgressDialog.show(a,"正在打开剧集",route.name,true,true);wait.setOnCancelListener(x->state.token++);IO.execute(()->{try{JSONObject stream=stream(a,session,route,35000);a.runOnUiThread(()->{wait.dismiss();if(!alive(a)||state.token!=token)return;try{JSONObject previous=meta(a);FusionPlaybackRules.Episode wanted=FusionPlaybackRules.episode(previous.optString("subtitleEpisode"),""),chosen=FusionPlaybackRules.episode(route.name,route.flag+" "+detail.optString("vod_name"));boolean same=FusionPlaybackRules.episodeKey(previous.optString("subtitleEpisode")).equals(FusionPlaybackRules.episodeKey(route.name))||(wanted.number>0&&wanted.number==chosen.number&&(chosen.season<0||wanted.season<0||chosen.season==wanted.season));if(same){apply(a,session,stream,route.name);meta(a).put("fusion.video",detail.optString("vod_id")).put("fusion.flag",route.flag);return;}Object playerSession=OnlineSubtitleSearch.field(a,"session");if(playerSession!=null)OnlineSubtitleSearch.call(playerSession,"checkpoint",new Class<?>[0]);String watch="tvbox:"+TvSpiderRules.digest((session.url+"|"+session.site.optString("key")+"|"+detail.optString("vod_id")+"|"+route.name).getBytes("UTF-8"),"SHA-256");int resume=Math.max(0,a.getSharedPreferences("data",0).getInt("pos:"+watch,0));SourceSubtitleLoader.set(a,"id",watch);SourceSubtitleLoader.set(a,"resumePos",resume);SourceSubtitleLoader.set(a,"prepared",false);if(playerSession!=null)SourceSubtitleLoader.set(playerSession,"pendingResume",resume);SourceSubtitleLoader.set(a,"cues",new ArrayList<>());Object sub=OnlineSubtitleSearch.field(a,"sub");if(sub instanceof TextView)((TextView)sub).setText("");Object generation=OnlineSubtitleSearch.field(a,"generation");if(generation instanceof Integer)SourceSubtitleLoader.set(a,"generation",(Integer)generation+1);String caption=title(previous)+" · "+route.name;int season=chosen.season>=0?chosen.season:wanted.season;String canonical=season>=0&&chosen.number>0?String.format(Locale.ROOT,"S%02dE%02d",season,chosen.number):route.name;previous.put("id",watch).put("name",caption).put("subtitleEpisode",canonical).put("fusion.video",detail.optString("vod_id")).put("fusion.flag",route.flag);SourceSubtitleLoader.set(a,"name",caption);Object top=OnlineSubtitleSearch.field(a,"top");if(top instanceof ViewGroup){ViewGroup g=(ViewGroup)top;for(int i=0;i<g.getChildCount();i++)if(g.getChildAt(i) instanceof TextView&&!(g.getChildAt(i) instanceof Button)){((TextView)g.getChildAt(i)).setText(caption);break;}}apply(a,session,stream,route.name);if(playerSession!=null)OnlineSubtitleSearch.call(playerSession,"start",new Class<?>[0]);}catch(Exception error){message(a,"选集切换失败："+error.getClass().getSimpleName());}});}catch(Exception e){a.runOnUiThread(()->{wait.dismiss();if(alive(a)&&state.token==token)message(a,"该集地址获取失败："+SourceSearchClient.reason(e)+"，未切换。");});}});}
 static void status(Activity a,String message){Object state=OnlineSubtitleSearch.field(a,"state");if(state instanceof TextView)((TextView)state).setText(message);}
 static void message(Activity a,String message){if(alive(a))new AlertDialog.Builder(a).setTitle("影视仓源").setMessage(message).setPositiveButton("确定",null).show();}
}
